/*
 * Deterministic builder for js/pixel-templates.js.
 *
 * The art lives in scripts/pixel-template-art.js as 16x16 '#'/'.' grids. This
 * module converts it to the runtime 0/1 rows and renders the exact source text.
 * scripts/build-pixel-templates.js writes that text; the test renders it again
 * and compares, so the committed data can never drift from the art.
 */
'use strict';

const { TEMPLATES } = require('../pixel-template-art.js');

const HEADER = [
    '/*',
    ' * Pixel tracing templates.',
    ' *',
    ' * Generated by scripts/build-pixel-templates.js from the hand-authored grids',
    ' * in scripts/pixel-template-art.js. Do not hand-edit: re-run',
    ' * `node scripts/build-pixel-templates.js` after changing the art.',
    ' * Each row is `size` characters; 1 = ink, 0 = empty.',
    ' */',
    ''
].join('\n');

function validateArt() {
    const ids = new Set();
    const names = new Set();
    if (!Array.isArray(TEMPLATES) || TEMPLATES.length === 0) {
        throw new Error('pixel-template-art.js must export a non-empty TEMPLATES array');
    }
    TEMPLATES.forEach(function (t) {
        if (!t || typeof t.id !== 'string' || !/^[a-z][a-zA-Z0-9]*$/.test(t.id)) {
            throw new Error('template needs a camelCase id: ' + JSON.stringify(t && t.id));
        }
        if (ids.has(t.id)) throw new Error('duplicate template id: ' + t.id);
        ids.add(t.id);
        if (typeof t.name !== 'string' || !t.name) throw new Error('template needs a name: ' + t.id);
        if (names.has(t.name)) throw new Error('duplicate template name: ' + t.name);
        names.add(t.name);
        if (typeof t.category !== 'string' || !t.category) throw new Error('template needs a category: ' + t.id);
        if (!Array.isArray(t.rows)) throw new Error('template needs rows: ' + t.id);
        const size = t.rows.length;
        if (size !== 16 && size !== 32) throw new Error('template size must be 16 or 32: ' + t.id);
        let ink = 0;
        t.rows.forEach(function (row, index) {
            if (typeof row !== 'string' || row.length !== size) {
                throw new Error('row ' + index + ' of ' + t.id + ' must be ' + size + ' characters');
            }
            if (!/^[#.]+$/.test(row)) {
                throw new Error('row ' + index + ' of ' + t.id + ' may only contain # and .');
            }
            for (let i = 0; i < row.length; i++) if (row.charAt(i) === '#') ink++;
        });
        if (ink < 16) throw new Error('template has too little ink: ' + t.id);
    });
    return TEMPLATES.length;
}

function buildTemplates() {
    validateArt();
    return TEMPLATES.map(function (t) {
        const size = t.rows.length;
        const rows = t.rows.map(function (row) {
            let bits = '';
            for (let i = 0; i < row.length; i++) bits += row.charAt(i) === '#' ? '1' : '0';
            return bits;
        });
        return {
            id: t.id,
            name: t.name,
            category: t.category,
            size: size,
            rows: rows
        };
    });
}

function renderSource() {
    return HEADER + 'window.REKINDLE_PIXEL_TEMPLATES = '
        + JSON.stringify(buildTemplates(), null, 4)
        + ';\n';
}

module.exports = {
    HEADER: HEADER,
    buildTemplates: buildTemplates,
    renderSource: renderSource
};
